var fs = require('fs');
var toks = [];

function lex(src) {
  var i = 0;
  while (i < src.length) {
    var c = src[i];
    if (c === ' ' || c === '\n') { i++; continue; }
    if (c === '(' || c === ')') {
      toks.push(c);
      i++;
      continue;
    }
    throw new Error('bad char ' + c + ' at ' + i);
  }
  return toks;
}

function dump() {
  for (var k = 0; k < toks.length; k++) {
    console.log(k, toks[k]);
  }
}

var src = fs.readFileSync(process.argv[2], 'utf8');
lex(src);
dump();

